/**
 * DOM Element Manager for safe element access and manipulation.
 *
 * Features:
 * - Caches element references for better performance
 * - Provides safe visibility toggles
 * - Handles missing elements gracefully
 * - Convenient helper methods for common operations
 *
 * @module mod_tutoom/lib/dom_manager
 * @copyright 2025 onwards, Tutoom Inc.
 * @license http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

/**
 * DOM Manager class for element access and manipulation.
 */
export class DomManager {
  /**
   * Constructor - initializes element cache.
   */
  constructor() {
    this.cache = {};
  }

  /**
   * Get DOM element by ID (with caching).
   *
   * @param {string} elementId - Element ID to retrieve
   * @returns {HTMLElement|null} DOM element or null if not found
   */
  get(elementId) {
    if (!this.cache[elementId]) {
      const el = document.getElementById(elementId);
      if (!el) {
        console.warn(`Element not found: ${elementId}`);
        return null;
      }
      this.cache[elementId] = el;
    }
    return this.cache[elementId];
  }

  /**
   * Show element (set display to flex).
   *
   * @param {string} elementId - Element ID to show
   * @returns {HTMLElement|null} The element or null if not found
   */
  show(elementId) {
    const el = this.get(elementId);
    if (el) {
      el.style.display = "flex";
    }
    return el;
  }

  /**
   * Hide element (set display to none).
   *
   * @param {string} elementId - Element ID to hide
   * @returns {HTMLElement|null} The element or null if not found
   */
  hide(elementId) {
    const el = this.get(elementId);
    if (el) {
      el.style.display = "none";
    }
    return el;
  }

  /**
   * Toggle element visibility.
   *
   * @param {string} elementId - Element ID to toggle
   * @param {boolean} visible - True to show, false to hide
   * @returns {HTMLElement|null} The element or null if not found
   */
  toggle(elementId, visible) {
    return visible ? this.show(elementId) : this.hide(elementId);
  }

  /**
   * Clear element innerHTML.
   *
   * @param {string} elementId - Element ID to clear
   * @returns {HTMLElement|null} The element or null if not found
   */
  clear(elementId) {
    const el = this.get(elementId);
    if (el) {
      el.innerHTML = "";
    }
    return el;
  }

  /**
   * Clear element cache (useful for testing or dynamic content).
   *
   * @returns {void}
   */
  clearCache() {
    this.cache = {};
  }
}
